#include "unity.h"
#include "buffer.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_buffer_new_with_string_basic_string_copy(void) {
    // Setup: create a valid null-terminated string
    char *test_str = strdup("Hello, world!");

    // Test: call buffer_new_with_string
    buffer_t *buf = buffer_new_with_string(test_str);

    // Assertions
    TEST_ASSERT_NOT_NULL(buf);
    helper_assert_buffer_content(buf, "Hello, world!");
    helper_assert_buffer_length(buf, 13); // strlen("Hello, world!") == 13

    // Cleanup
    buffer_free(buf);
    free(test_str);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_new_with_string_basic_string_copy);
    return UNITY_END();
}


